def build_all_vocab_files(out_dir: str):
    os.makedirs(out_dir, exist_ok=True)
    all_raw = CET4_CET6_WORDS + MORE_WORDS
    structured = []
    for idx, item in enumerate(all_raw, start=1):
        word, uk, us, cn, en, syn, ex_en, ex_cn, tip, books, freq = item
        w_norm = word[0].lower() + word[1:] if word == "Available" or word == "Sustain" else word
        structured.append({
            "id": f"voca_{idx:04d}",
            "seq": idx,
            "word": w_norm,
            "uk": uk,
            "us": us,
            "cn": cn,
            "en": en,
            "syn": syn,
            "ex_en": ex_en,
            "ex_cn": ex_cn,
            "tip": tip,
            "books": books,
            "freq": freq
        })

    # 1. Write JSON lexicon
    json_path = os.path.join(out_dir, "voca_lexicon.json")
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(structured, f, ensure_ascii=False, indent=2)

    # 2. Write SQLite3 database (voca_lexicon.db)
    db_path = os.path.join(out_dir, "voca_lexicon.db")
    if os.path.exists(db_path):
        os.remove(db_path)
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    cur.executescript("""
        CREATE TABLE metadata (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );
        CREATE TABLE books (
            book_id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            subtitle TEXT NOT NULL,
            license_source TEXT NOT NULL,
            word_count INTEGER NOT NULL
        );
        CREATE TABLE words (
            id TEXT PRIMARY KEY,
            seq INTEGER NOT NULL,
            word TEXT NOT NULL,
            uk_ipa TEXT NOT NULL,
            us_ipa TEXT NOT NULL,
            cn_def TEXT NOT NULL,
            en_def TEXT NOT NULL,
            synonyms_json TEXT NOT NULL,
            example_en TEXT NOT NULL,
            example_cn TEXT NOT NULL,
            mnemonic_tip TEXT NOT NULL,
            books_json TEXT NOT NULL,
            freq_star INTEGER NOT NULL
        );
        CREATE TABLE user_word_records (
            word_id TEXT PRIMARY KEY,
            unfamiliar_level INTEGER DEFAULT 0,
            is_starred INTEGER DEFAULT 0,
            is_mastered INTEGER DEFAULT 0,
            custom_cn_def TEXT,
            custom_note TEXT,
            review_count INTEGER DEFAULT 0,
            last_reviewed_at TEXT
        );
        CREATE TABLE ebbinghaus_plans (
            plan_id TEXT PRIMARY KEY,
            book_id TEXT NOT NULL,
            total_lists INTEGER NOT NULL,
            order_mode TEXT NOT NULL,
            created_at TEXT NOT NULL,
            completed_cells_json TEXT NOT NULL
        );
        CREATE INDEX idx_words_word ON words(word);
    """)
    cur.executemany("INSERT INTO metadata VALUES (?, ?)", [
        ("app_name", "Voca"),
        ("schema_version", "1.0.0"),
        ("ebbinghaus_intervals", "1,2,4,7,15"),
        ("license", "Public Domain Exam Syllabi + Open ECDIC/WordNet/Tatoeba (CC-BY/MIT)"),
    ])
    for bid, title, sub, lic in [
        ("all", "Voca 全阶段精选核心大纲总词库", "涵盖四级、六级、2027考研及学术英语核心词汇", "Public Syllabus + Open WordNet/ECDIC"),
        ("cet4", "大学英语四级 (CET-4) 核心词库", "教育部大学英语四级考试高频核心词表", "教育部四级公共教学大纲 + 开放释义"),
        ("cet6", "大学英语六级 (CET-6) 核心词库", "教育部大学英语六级考试高频核心词表", "教育部六级公共教学大纲 + 开放释义"),
        ("kaoyan", "2027 硕士研究生英语（一/二）核心词库", "含考研高频熟词僻义、词根词缀及真题级语境例句", "全国硕士研究生招生考试英语公共大纲 + 开放释义"),
        ("academic", "IELTS / TOEFL 学术英语核心词库 (AWL)", "国际学术阅读与写作核心高频词汇", "Academic Word List (Coxhead) + WordNet 3.1"),
    ]:
        cnt = len(structured) if bid == "all" else sum(1 for w in structured if bid in w["books"])
        cur.execute("INSERT INTO books VALUES (?, ?, ?, ?, ?)", (bid, title, sub, lic, cnt))

    for w in structured:
        cur.execute(
            "INSERT INTO words VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                w["id"], w["seq"], w["word"], w["uk"], w["us"],
                w["cn"], w["en"], json.dumps(w["syn"], ensure_ascii=False),
                w["ex_en"], w["ex_cn"], w["tip"],
                json.dumps(w["books"], ensure_ascii=False), w["freq"]
            )
        )
    conn.commit()
    conn.close()

    # 3. Write Standard CSV import/export file
    csv_path = os.path.join(out_dir, "voca_standard_lexicon.csv")
    with open(csv_path, "w", encoding="utf-8-sig", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["word", "uk_ipa", "us_ipa", "cn_def", "en_def", "synonyms", "example_en", "example_cn", "mnemonic_tip", "books", "freq_star"])
        for w in structured:
            writer.writerow([
                w["word"], w["uk"], w["us"], w["cn"], w["en"],
                "; ".join(w["syn"]), w["ex_en"], w["ex_cn"], w["tip"],
                ",".join(w["books"]), w["freq"]
            ])

    # 4. Write a Sample Custom Import CSV & TXT for users to test importing
    sample_csv = os.path.join(out_dir, "sample_custom_import.csv")
    with open(sample_csv, "w", encoding="utf-8-sig", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["word", "phonetic", "definition", "example_en", "example_cn", "note"])
        writer.writerow(["serendipity", "/ˌserənˈdɪpəti/", "n. 意外发现珍奇事物的本领；机缘巧合", "Finding that rare book in a small shop was pure serendipity.", "在一家小店里淘到那本珍稀书籍纯属机缘巧合。", "助记：源自古老童话《锡兰三王子》"])
        writer.writerow(["epiphany", "/ɪˈpɪfəni/", "n. 顿悟，醍醐灌顶的领悟", "She had an epiphany about how memory curves work.", "她对记忆曲线的运作原理有了醍醐灌顶般的领悟。", "词根：epi(在上面)+phan(显现)+y → 灵光乍现"])
        writer.writerow(["ubiquity", "/juːˈbɪkwəti/", "n. 无处不在，普遍存在", "The ubiquity of mobile devices makes offline study convenient.", "移动设备的普及让离线学习变得十分便利。", "派生自 ubiquitous（无处不在的）"])
        writer.writerow(["quintessential", "/ˌkwɪntɪˈsenʃl/", "adj. 最典型的，精髓的，极具代表性的", "Spaced repetition is the quintessential method for long-term retention.", "间隔重复是实现长期记忆最典型的方法。", "词根：quint(第五)+essent(本质)+ial → 第五元素/精华"])
        writer.writerow(["eloquent", "/ˈeləkwənt/", "adj. 雄辩的，有说服力的，流利的", "She gave an eloquent defense of open-source educational software.", "她为开源教育软件做了一场雄辩有力的辩护。", "词根：e(出)+loqu(说)+ent → 说得极其出色的"])

    print(f"Generated {len(structured)} words -> JSON ({os.path.getsize(json_path)} B), SQLite ({os.path.getsize(db_path)} B), CSV ({os.path.getsize(csv_path)} B)")

if __name__ == "__main__":
    build_all_vocab_files("./build_output")
